 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 SELECT j IS NOT NULL AND jsonb_typeof(j)='array' AND jsonb_array_length(j)<=3 AND NOT EXISTS(
